import os
root='/challenge/inhere'
firsts={}
for dp,_,fns in os.walk(root):
    for fn in sorted(fns):
        p=os.path.join(dp,fn)
        data=open(p,'rb').read()
        fl=data.split(b'\n')[0][:60]
        firsts.setdefault(fl,[]).append(p)
for k,v in firsts.items():
    print(len(v), repr(k), '->', v[0])
