python3 - <<'EOF'
import os, hashlib
print('zeros md5:', hashlib.md5(b'\x00'*1033).hexdigest())
print('xs md5   :', hashlib.md5(b'x'*1033).hexdigest())
root='/challenge/inhere'
for dp,_,fns in os.walk(root):
    for fn in fns:
        p=os.path.join(dp,fn)
        try:
            xa=os.listxattr(p)
            if xa: print('XATTR',p,xa, [os.getxattr(p,a) for a in xa])
        except Exception as e:
            print('ERR',p,e)
print('xattr scan done')
EOF

